SET NAMES utf8mb4;
UPDATE product SET subtitle_it='Un olio extravergine elegante e armonico, ottenuto dalle olive raccolte a mano nelle colline venete ai piedi del Monte Pizzoc.', subtitle_en='An elegant, harmonious extra virgin olive oil, made from olives picked by hand on the Venetian hills at the foot of Monte Pizzoc.', description_it='Ogni bottiglia nasce da un equilibrio naturale unico: giornate di sole, aria fresca di montagna e una terra generosa.\n\nLe olive maturano lentamente, sviluppando un profilo raffinato, con note equilibrate e una struttura intensa ma armoniosa.\n\nÈ un olio pensato per chi cerca autenticità, eleganza e origine.', description_en='Every bottle is born from a unique natural balance: sunny days, fresh mountain air and a generous land.\n\nThe olives ripen slowly, developing a refined profile, with balanced notes and an intense yet harmonious structure.\n\nIt is an oil for those who look for authenticity, elegance and origin.', tastingNotes_it='Equilibrato e armonico, con note fresche e una leggera intensità finale.', tastingNotes_en='Balanced and harmonious, with fresh notes and a light intensity on the finish.', pairings_it='Perfetto a crudo su:\n- Pane caldo\n- Verdure grigliate\n- Pesce\n- Piatti semplici dove l''olio è protagonista', pairings_en='Perfect raw on:\n- Warm bread\n- Grilled vegetables\n- Fish\n- Simple dishes where the oil takes centre stage', cultivar='Leccino, Pendolino, Ascolana, Frantoio' WHERE slug='selezione-monte-pizzoc';
